      { q: "What does Lindiwe M. believe is missing from the current debate?", options: ["Employee opinions", "Reliable data measuring whether productivity has actually changed under hybrid arrangements", "A vote among city council members", "A comparison to other cities' office space costs"], answer: 1 },
      { q: "What does Lindiwe M. recommend before any policy is mandated?", options: ["Immediately mandating the policy without further study", "Measuring outcomes for at least two full quarters first", "Cancelling remote work immediately", "Asking only office-based employees for input"], answer: 1 },
      { q: "Which writer raises a concern specifically about fairness between different types of city jobs?", options: ["Grzegorz W.", "Fatoumata B.", "Rasheed O.", "Lindiwe M."], answer: 2 },
      { q: "Which two writers focus their argument on how the decision should be made rather than what the outcome should be?", options: ["Grzegorz W. and Fatoumata B.", "Rasheed O. and Lindiwe M.", "Fatoumata B. and Lindiwe M.", "Grzegorz W. and Lindiwe M."], answer: 2 }
